import{_ as e,o,c as d,a2 as r}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"文档同步规范（三模式通用）","description":"","frontmatter":{"title":"文档同步规范（三模式通用）"},"headers":[],"relativePath":"dev-flow/references/doc-sync-rules.md","filePath":"dev-flow/references/doc-sync-rules.md","lastUpdated":null}'),a={name:"dev-flow/references/doc-sync-rules.md"};function c(n,t,i,l,s,h){return o(),d("div",null,[...t[0]||(t[0]=[r('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/doc-sync-rules.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="文档同步规范-三模式通用" tabindex="-1">文档同步规范（三模式通用） <a class="header-anchor" href="#文档同步规范-三模式通用" aria-label="Permalink to &quot;文档同步规范（三模式通用）&quot;">​</a></h1><p>涉及三类文档（工作上下文、开发日志、技术方案文档）的同步规范。</p><h2 id="主动同步-编码后" tabindex="-1">主动同步（编码后） <a class="header-anchor" href="#主动同步-编码后" aria-label="Permalink to &quot;主动同步（编码后）&quot;">​</a></h2><p>编码过程中按四个时机由轻到重递进执行文档同步：① 编码后（仅更新工作上下文进度）→ ② 验证前（三件套同步）→ ③ Commit/收尾（兜底检查）→ ④ 归档（完整同步）。</p><h2 id="被动同步-外部文档变更-内部需求漂移" tabindex="-1">被动同步（外部文档变更 / 内部需求漂移） <a class="header-anchor" href="#被动同步-外部文档变更-内部需求漂移" aria-label="Permalink to &quot;被动同步（外部文档变更 / 内部需求漂移）&quot;">​</a></h2><p>当用户告知外部文档发生变更、或带外沟通后回流澄清结论时触发。<strong>必须在动手改代码之前</strong>完成相应同步流程。</p><h3 id="触发关键词-指针引用-单一权威源" tabindex="-1">触发关键词（指针引用，单一权威源） <a class="header-anchor" href="#触发关键词-指针引用-单一权威源" aria-label="Permalink to &quot;触发关键词（指针引用，单一权威源）&quot;">​</a></h3><blockquote><p>🔒 <strong>单一权威源原则</strong>：本规范不再独立维护关键词清单。所有触发关键词以 <code>~/.codebuddy/skills/tech-doc/config/triggers.yaml</code> 为程序化权威源，本文件仅做语义分类描述与路由说明。增删关键词请直接修改 yaml。</p></blockquote><table tabindex="0"><thead><tr><th>类别</th><th>语义</th><th>权威源节点</th></tr></thead><tbody><tr><td><strong>A. 外部文档变更</strong></td><td>文档平台/Figma/protobuf 等外部文档/协议变更通告</td><td><code>triggers.yaml</code> → <code>doc_sync.explicit</code> + <code>doc_sync.passive_sync</code></td></tr><tr><td><strong>B. 沟通结果回流</strong></td><td>与产品/设计/后端 沟通后回流澄清结论</td><td><code>triggers.yaml</code> → <code>working_context_drift.communication_feedback</code></td></tr><tr><td><strong>C. 需求/方案否定</strong></td><td>用户带方向性地推翻既有方案/需求</td><td><code>triggers.yaml</code> → <code>working_context_drift.requirement_negation</code></td></tr><tr><td><strong>D. 澄清式调整</strong></td><td>修正性补充，调整既有理解的细节</td><td><code>triggers.yaml</code> → <code>working_context_drift.clarification</code></td></tr></tbody></table><p><strong>注</strong>：A 类与 B/C/D 类边界由 <code>triggers.yaml</code> <code>working_context_drift.boundary_with_doc_sync</code> 定义；同时命中（如「需求变更」+ 文档平台 链接）时按其规则解析。</p><h2 id="路由分流-v1-新增-2026-05-19" tabindex="-1">路由分流（v1 新增 2026-05-19） <a class="header-anchor" href="#路由分流-v1-新增-2026-05-19" aria-label="Permalink to &quot;路由分流（v1 新增 2026-05-19）&quot;">​</a></h2><p>触发后按变更类型分流，避免不同性质的变更走同一路径导致漏处理：</p><table tabindex="0"><thead><tr><th>变更类型</th><th>检测信号</th><th>路由目的地</th></tr></thead><tbody><tr><td>外部文档变更（文档平台/Figma/protobuf）</td><td>用户贴出新链接/新结构定义，或命中 A 类关键词</td><td><code>use_skill(&#39;tech-doc&#39;)</code> 路由到 doc-sync 模块，按 §三「强制执行步骤」逐步执行</td></tr><tr><td><strong>内部需求/方案漂移</strong>（无外部文档变化）</td><td>仅口头澄清/IM 沟通结果，命中 B/C/D 类关键词</td><td><strong><code>references/drift-handling.md</code></strong></td></tr><tr><td>两者兼有</td><td>用户同时贴新链接 + 说明调整</td><td>先走外部 doc-sync，再走内部漂移子流程</td></tr></tbody></table><h2 id="触发后行为-外部文档变更场景" tabindex="-1">触发后行为（外部文档变更场景） <a class="header-anchor" href="#触发后行为-外部文档变更场景" aria-label="Permalink to &quot;触发后行为（外部文档变更场景）&quot;">​</a></h2><p>调用 <code>use_skill(&#39;tech-doc&#39;)</code>（路由到 doc-sync 模块）加载完整文档同步规范，按 §三「强制执行步骤」逐步执行。</p><h2 id="触发后行为-内部需求漂移场景" tabindex="-1">触发后行为（内部需求漂移场景） <a class="header-anchor" href="#触发后行为-内部需求漂移场景" aria-label="Permalink to &quot;触发后行为（内部需求漂移场景）&quot;">​</a></h2><p>加载 <code>references/drift-handling.md</code>，按其三步固定动作（静默对账 → 输出漂移摘要 + 决策选项 → 执行刷新）执行。<strong>禁止跳过强制交互</strong>，避免 AI 自行揣测漂移程度。</p><h2 id="反模式-违反即拒收" tabindex="-1">反模式（违反即拒收） <a class="header-anchor" href="#反模式-违反即拒收" aria-label="Permalink to &quot;反模式（违反即拒收）&quot;">​</a></h2><ul><li>❌ 命中 B/C/D 类关键词后只更新代码不刷新工作上下文 → 跨会话恢复时 AI 仍读到旧需求</li><li>❌ 命中 A 类关键词后跳过 doc-sync 模块直接改代码 → 文档平台/Figma 与代码漂移</li><li>❌ AI 静默判定「这次澄清不重要」而不输出漂移摘要 → 违反「需求理解优先」红线</li><li>❌ 在本文件复制粘贴关键词清单 → 违反单一权威源原则（应改 <code>triggers.yaml</code>）</li></ul><h2 id="与既有机制的关系" tabindex="-1">与既有机制的关系 <a class="header-anchor" href="#与既有机制的关系" aria-label="Permalink to &quot;与既有机制的关系&quot;">​</a></h2><ul><li><strong>与 <code>~/.codebuddy/skills/tech-doc/config/triggers.yaml</code> 同步</strong>：本规范是 yaml 中 <code>doc_sync</code> + <code>working_context_drift</code> 节点的路由消费者，不重复维护关键词；增删关键词只改 yaml</li><li><strong>与 <code>references/iteration-fix.md</code> 互补</strong>：iteration-fix 是「提测/上线后」的修复路径，本规范覆盖「开发中」的澄清回流，二者正交</li><li><strong>与 <code>### 恢复指令</code> 三段式同步</strong>：漂移刷新后必须同步更新 <code>.flow.recovery.yesterday/next_action/pending</code>，避免双源不一致</li><li><strong>与 <code>## 约束与决策</code> 删除线规范复用</strong>：本规范不重新定义旧决策的标记格式，统一使用 <code>~~删除线~~</code>（详见 <code>references/working-context.md</code> § 字段说明 中「约束与决策」行）</li></ul>',22)])])}const f=e(a,[["render",c]]);export{u as __pageData,f as default};
